#DIM status AS %Status set status = $$$OK try{ $$$TRACE("Enter jCipher...") set iStr = pRequest.data Set tSC = ..GetConnection(.tJavaGateway) If $$$ISOK(tSC){ $$$TRACE("Get keyGenerator instance...") Set keyByteStream=##class(%GlobalBinaryStream).%New() Do keyByteStream.Write($C(0)) Do keyByteStream.Write($C(1)) Do keyByteStream.Write($C(2)) Do keyByteStream.Write($C(3)) Do keyByteStream.Write($C(4)) Do keyByteStream.Write($C(5)) Do keyByteStream.Write($C(6)) Do keyByteStream.Write($C(7))
///Do keyByteStream.Rewind() $$$TRACE("Get secret key instance...") set sKey = ##class(javax.crypto.spec.SecretKeySpec).%New(tJavaGateway,keyByteStream,"DES") set pResponse=##class(Ens.StringResponse).%New() set pResponse.StringValue="" $$$TRACE("Got Instance of the keyGenerator...")
$$$TRACE("Do Cipher encryption...")
set desCipher = ##class(javax.crypto.Cipher).getInstance(tJavaGateway, pRequest.cipherType) If '$IsObject(desCipher){ $$$TRACE(">>>>>Can't get a Cipher object.") Set sc = $System.Status.Error($$$GeneralError,"Can't get a Cipher instance.") Quit } $$$TRACE("Got a Instance of the Cipher...") do desCipher.init(##class(javax.crypto.Cipher).#ENCRYPTuMODE,sKey) $$$TRACE("Cipher Instance is inited.") Set byteStream=##class(%GlobalBinaryStream).%New() Do byteStream.Write(iStr) set desStrBytes=desCipher.doFinal(byteStream) set desStr=desStrBytes.Read(desStrBytes.SizeGet()) $$$TRACE("Encrypted string:"_desStr) set pResponse.StringValue=desStr Kill keyByteStream Kill byteStream Kill tJavaGateway } }catch err{ Kill tJavaGateway $$$TRACE("Exception Calling CipherEncription " _ err) set status = $$$ERROR("Exception in CipherEncription Operation") }
return status
